// Process Google Apps Script response
const response = $json;

// Check if we got a valid LinkedIn URL
if (response.success && response.linkedinUrl) {
  return {
    ...response,
    linkedinUrl: response.linkedinUrl,
    profileScore: response.score || 0,
    searchStrategy: response.strategyUsed || 'unknown',
    validationPassed: true
  };
} else {
  // No profile found or low confidence
  return {
    ...response,
    linkedinUrl: null,
    profileScore: 0,
    searchStrategy: 'none',
    validationPassed: false,
    error: response.error || 'Profile not found'
  };
}

const title = $json.title ? $json.title.toUpperCase() : '';
let campaignType = 'General';

if (['CHIEF', 'PRESIDENT', 'CEO', 'CFO', 'CTO', 'CIO', 'CMO'].some(t => title.includes(t))) {
    campaignType = 'C-Suite';
} else if (['IT', 'DIGITAL', 'TECHNOLOGY', 'INFORMATICS', 'DATA'].some(t => title.includes(t))) {
    campaignType = 'IT-Digital';
} else if (['PATIENT', 'EXPERIENCE', 'QUALITY', 'CLINICAL'].some(t => title.includes(t))) {
    campaignType = 'Patient-Experience';
} else if (['REVENUE', 'OPERATIONS', 'FINANCE', 'RCM'].some(t => title.includes(t))) {
    campaignType = 'Operations-Revenue';
}

return {
    ...$json,
    campaignType,
    linkedinUrl: $json.linkedinUrl,
    status: $json.linkedinUrl ? 'ready_to_connect' : 'profile_not_found',
    enrichmentDate: new Date().toISOString(),
    profileScore: $json.profileScore || 0
};

// Transform Bright Data response to standardized format
const rawData = $json;

function transformProfile(raw) {
  // Handle potential error responses
  if (raw.error || raw.status === 'error') {
    throw new Error(`Bright Data API error: ${raw.error || raw.message || 'Unknown error'}`);
  }

  // Extract profile ID from URL
  const profileId = raw.url ? raw.url.match(/\/in\/([^\/\?]+)/)?.[1] : null;

  return {
    // Basic Information
    profileId: profileId || `profile_${Date.now()}`,
    fullName: raw.name || '',
    headline: raw.headline || '',
    location: raw.location || '',
    profileUrl: raw.url || $json.linkedinUrl,
    profileImageUrl: raw.profile_image || '',

    // Professional Information
    currentPosition: {
      title: raw.current_position?.title || '',
      company: raw.current_position?.company || '',
      startDate: raw.current_position?.start_date || '',
      description: raw.current_position?.description || ''
    },

    // Experience
    experience: (raw.experience || []).map(exp => ({
      title: exp.title || '',
      company: exp.company || '',
      duration: exp.duration || '',
      startDate: exp.start_date || '',
      endDate: exp.end_date || '',
      description: exp.description || ''
    })),

    // Education
    education: (raw.education || []).map(edu => ({
      school: edu.school || '',
      degree: edu.degree || '',
      field: edu.field || '',
      startDate: edu.start_date || '',
      endDate: edu.end_date || ''
    })),

    // Skills
    skills: raw.skills || [],

    // Network
    connectionsCount: raw.connections || 0,
    followersCount: raw.followers || 0,

    // Recent Activity
    recentPosts: (raw.activity?.posts || []).slice(0, 5).map(post => ({
      text: post.text || '',
      date: post.date || '',
      likes: post.likes || 0,
      comments: post.comments || 0
    })),

    // Company Details
    companyDetails: raw.company_details ? {
      name: raw.company_details.name || '',
      size: raw.company_details.size || '',
      industry: raw.company_details.industry || '',
      type: raw.company_details.type || '',
      headquarters: raw.company_details.headquarters || ''
    } : null,

    // Summary and About
    summary: raw.summary || raw.about || '',

    // Metadata
    enrichmentDate: new Date().toISOString(),
    dataSource: 'bright_data',
    dataCompleteness: calculateCompleteness(raw)
  };
}

function calculateCompleteness(raw) {
  const fields = [
    raw.name,
    raw.headline,
    raw.current_position?.title,
    raw.experience?.length > 0,
    raw.education?.length > 0,
    raw.skills?.length > 0,
    raw.summary || raw.about
  ];
  const filled = fields.filter(f => f).length;
  return Math.round((filled / fields.length) * 100);
}

try {
  const transformedProfile = transformProfile(rawData);
  return transformedProfile;
} catch (error) {
  // Return error but don't stop the workflow
  return {
    error: error.message,
    profileUrl: $json.linkedinUrl,
    enrichmentFailed: true,
    enrichmentDate: new Date().toISOString()
  };
}

